from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        total = sum(nums)
        if k < -total or k > total:
            return -1

        offset = total
        target = offset + k

        # exact0[p]: bitset of alternating sums for even-length subsequences
        # exact1[p]: bitset of alternating sums for odd-length subsequences
        # product p is in [0, limit]
        exact0 = [0] * (limit + 1)
        exact1 = [0] * (limit + 1)

        # big0/big1: same, but for non-empty subsequences whose product > limit.
        # Needed because multiplying later by 0 can make the final product 0.
        big0 = 0
        big1 = 0

        for x in nums:
            old0, old1 = exact0, exact1
            old_big0, old_big1 = big0, big1

            # Skip current number.
            new0 = old0.copy()
            new1 = old1.copy()
            new_big0 = old_big0
            new_big1 = old_big1

            if x == 0:
                # Append 0 to any existing subsequence:
                # product becomes 0, sum unchanged, parity flips.
                agg0 = old_big0
                for b in old0:
                    if b:
                        agg0 |= b

                agg1 = old_big1
                for b in old1:
                    if b:
                        agg1 |= b

                if agg0:
                    new1[0] |= agg0
                if agg1:
                    new0[0] |= agg1

                # Start a new subsequence [0].
                new1[0] |= 1 << offset

                exact0, exact1, big0, big1 = new0, new1, new_big0, new_big1
                continue

            # x > 0
            start_bit = 1 << (offset + x)

            # Start a new subsequence [x].
            if x <= limit:
                new1[x] |= start_bit
            else:
                new_big1 |= start_bit

            if x == 1:
                # Product does not change.
                for p in range(limit + 1):
                    b = old0[p]
                    if b:
                        new1[p] |= b << 1

                    b = old1[p]
                    if b:
                        new0[p] |= b >> 1
            else:
                max_exact = limit // x

                # Transitions that keep product within limit.
                for p in range(max_exact + 1):
                    b = old0[p]
                    if b:
                        new1[p * x] |= b << x

                    b = old1[p]
                    if b:
                        new0[p * x] |= b >> x

                # Transitions that make product exceed limit.
                if max_exact < limit:
                    for p in range(max_exact + 1, limit + 1):
                        b = old0[p]
                        if b:
                            new_big1 |= b << x

                        b = old1[p]
                        if b:
                            new_big0 |= b >> x

            # Append x to already-too-large nonzero products.
            if old_big0:
                new_big1 |= old_big0 << x
            if old_big1:
                new_big0 |= old_big1 >> x

            exact0, exact1, big0, big1 = new0, new1, new_big0, new_big1

        # Products 0 through limit are valid; maximize by scanning downward.
        for p in range(limit, -1, -1):
            if ((exact0[p] | exact1[p]) >> target) & 1:
                return p

        return -1

import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    S = data[1]
    T = data[2]
    mp = [-1]*26
    for a,b in zip(S,T):
        u = ord(a)-97
        v = ord(b)-97
        if mp[u] == -1:
            mp[u] = v
        elif mp[u] != v:
            print(-1)
            return
    present = [mp[i] != -1 for i in range(26)]
    indeg = [0]*26
    m = 0
    for i in range(26):
        if present[i]:
            if mp[i] != i:
                m += 1
            indeg[mp[i]] += 1
    state = [0]*26
    pos = [-1]*26
    extra = 0
    for i in range(26):
        if not present[i] or state[i] != 0:
            continue
        v = i
        path = []
        while present[v] and state[v] == 0:
            state[v] = 1
            pos[v] = len(path)
            path.append(v)
            nv = mp[v]
            if not present[nv]:
                v = -1
                break
            v = nv
        if v != -1 and state[v] == 1:
            start = pos[v]
            if start != -1:
                cycle = path[start:]
                if len(cycle) >= 2:
                    ok = True
                    for node in cycle:
                        if indeg[node] != 1:
                            ok = False
                            break
                    if ok:
                        extra += 1
        for node in path:
            state[node] = 2
            pos[node] = -1
    if sum(present) == 26 and m > 0 and all(indeg[i] == 1 for i in range(26)):
        print(-1)
    else:
        print(m + extra)

