    solve()

import sys

def solve():
    s = sys.stdin.buffer.readline().strip()
    n = len(s)
    if n == 0:
        return

    rev = s[::-1]

    # Prefix function for rev
    pi = [0] * n
    for i in range(1, n):
        j = pi[i - 1]
        c = rev[i]
        while j and c != rev[j]:
            j = pi[j - 1]
        if c == rev[j]:
            j += 1
        pi[i] = j

    # KMP scan: longest prefix of rev that is a suffix of s
    j = 0
    for c in s:
        while j and c != rev[j]:
            j = pi[j - 1]
        if c == rev[j]:
            j += 1

    pal_len = j
    ans = s + s[:n - pal_len][::-1]
    sys.stdout.buffer.write(ans + b"\n")

if __name__ == "__main__":
    solve()

