def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    N = int(data[0])
    R = int(data[1])
    C = int(data[2])
    S = data[3].decode()

    offset = 2 * N + 5
    width = 4 * N + 11

    def encode(x, y):
        return (x + offset) * width + (y + offset)

    seen = set()
    seen.add(encode(0, 0))

    r = 0
    c = 0
    ans = []

    for ch in S:
        if ch == 'N':
            r -= 1
        elif ch == 'S':
            r += 1
        elif ch == 'W':
            c -= 1
        else:  # 'E'
            c += 1

        seen.add(encode(r, c))

        if encode(r - R, c - C) in seen:
            ans.append('1')
        else:
            ans.append('0')

    sys.stdout.write(''.join(ans))

if __name__ == "__main__":
    main()

