def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    it = iter(data)
    N = next(it)
    M = next(it)

    adj = [[] for _ in range(N)]
    for _ in range(M):
        u = next(it) - 1
        v = next(it) - 1
        adj[u].append(v)
        adj[v].append(u)

    color = [-1] * N

    isolated = 0          # odd components of size 1
    odd_nontrivial = 0    # odd components of size > 1
    even_both_odd = 0     # even components whose two color classes are both odd

    for s in range(N):
        if color[s] != -1:
            continue

        color[s] = 0
        stack = [s]
        c0 = 1
        c1 = 0

        while stack:
            u = stack.pop()
            cu = color[u]
            for v in adj[u]:
                if color[v] == -1:
                    color[v] = cu ^ 1
                    if color[v] == 0:
                        c0 += 1
                    else:
                        c1 += 1
                    stack.append(v)

        size = c0 + c1

        if size == 1:
            isolated += 1
        elif size & 1:
            odd_nontrivial += 1
        else:
            if (c0 & 1) and (c1 & 1):
                even_both_odd += 1

    if N & 1:
        win = (M & 1) == 1
    else:
        m_par = M & 1
        b_par = even_both_odd & 1

        if odd_nontrivial == 0:
            win = (m_par ^ b_par ^ ((isolated // 2) & 1)) == 1
        elif isolated == 0:
            if odd_nontrivial == 2:
                win = True
            else:
                win = (m_par == 1)
        else:
            r_mod = odd_nontrivial & 3
            if r_mod == 1 or r_mod == 2:
                win = True
            else:
                win = (m_par == 1)

    print("Aoki" if win else "Takahashi")

