from typing import List

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n - 1 < k:
            return [0] * n

        children = [{}]
        count = [0]
        depth = [0]
        terminals = [0] * n
        max_depth = 0

        for i, w in enumerate(words):
            node = 0
            for ch in w:
                c = ord(ch) - 97
                nxt = children[node].get(c)
                if nxt is None:
                    nxt = len(children)
                    children[node][c] = nxt
                    children.append({})
                    count.append(0)
                    depth.append(depth[node] + 1)
                    if depth[nxt] > max_depth:
                        max_depth = depth[nxt]
                node = nxt
                count[node] += 1
            terminals[i] = node

        size = len(children)
        cnt_ge = [0] * (max_depth + 1)
        unique = [0] * (max_depth + 1)

        for node in range(1, size):
            if count[node] >= k:
                d = depth[node]
                cnt_ge[d] += 1
                unique[d] = node

        global_all = 0
        for d in range(1, max_depth + 1):
            c = cnt_ge[d]
            if c >= 2:
                if d > global_all:
                    global_all = d
            elif c == 1:
                u = unique[d]
                if count[u] > k:
                    if d > global_all:
                        global_all = d

        special = []
        for d in range(1, max_depth + 1):
            if cnt_ge[d] == 1:
                u = unique[d]
                if count[u] == k and d > global_all:
                    special.append((d, u))

        if not special:
            return [global_all] * n

        special.sort(reverse=True)

        del cnt_ge, unique, count, depth

        tin = [0] * size
        tout = [0] * size
        time = 0
        stack = [0]

        while stack:
            node = stack.pop()
            if node >= 0:
                tin[node] = time
                time += 1
                stack.append(~node)
                stack.extend(children[node].values())
            else:
                tout[~node] = time

        del children

        special_info = [(d, tin[u], tout[u]) for d, u in special]
        ans = [global_all] * n

        for i, t in enumerate(terminals):
            tt = tin[t]
            for d, tin_u, tout_u in special_info:
                if not (tin_u <= tt < tout_u):
                    ans[i] = d
                    break

        return ans

