import math


def integer_cuberoot(n: int) -> int:
    lo, hi = 0, 10**6 + 2
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if mid * mid * mid <= n:
            lo = mid
        else:
            hi = mid
    return lo


def solve() -> None:
    data = sys.stdin.read().strip()
    if not data:
        return

    N = int(data)
    limit = integer_cuberoot(N)
    isqrt = math.isqrt

    for d in range(1, limit + 1):
        if N % d != 0:
            continue

        m = N // d
        a = 4 * m - d * d

        if a <= 0 or a % 3 != 0:
            continue

        q = a // 3
        t = isqrt(q)

        if t * t != q:
            continue

        if t <= d:
            continue

        if (t - d) % 2 != 0:
            continue

        y = (t - d) // 2
        x = y + d

        print(x, y)
        return

    print(-1)


