import sys
from collections import deque

sys.setrecursionlimit(1000000)


class Dinic:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        self.g[fr].append([to, cap, len(self.g[to])])
        self.g[to].append([fr, 0, len(self.g[fr]) - 1])

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        q = deque([s])
        while q:
            v = q.popleft()
            for to, cap, rev in self.g[v]:
                if cap > 0 and self.level[to] < 0:
                    self.level[to] = self.level[v] + 1
                    q.append(to)
        return self.level[t] >= 0

    def dfs(self, v, t, f):
        if v == t:
            return f
        while self.it[v] < len(self.g[v]):
            e = self.g[v][self.it[v]]
            if e[1] > 0 and self.level[v] + 1 == self.level[e[0]]:
                ret = self.dfs(e[0], t, min(f, e[1]))
                if ret:
                    e[1] -= ret
                    self.g[e[0]][e[2]][1] += ret
                    return ret
            self.it[v] += 1
        return 0

    def max_flow(self, s, t, limit=None):
        if limit is not None and limit <= 0:
            return 0
        flow = 0
        INF_FLOW = 10**18
        while self.bfs(s, t):
            self.it = [0] * self.n
            while True:
                f = INF_FLOW if limit is None else limit - flow
                ret = self.dfs(s, t, f)
                if not ret:
                    break
                flow += ret
                if limit is not None and flow >= limit:
                    return flow
        return flow


def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    K = int(next(it))

    edges = []
    adj = [[] for _ in range(N)]
    for _ in range(M):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        edges.append((u, v))
        adj[u].append(v)

    # Upper bound: unweighted shortest path length.
    dist = [-1] * N
    dist[0] = 0
    q = deque([0])
    while q:
        v = q.popleft()
        if v == N - 1:
            break
        for nv in adj[v]:
            if dist[nv] == -1:
                dist[nv] = dist[v] + 1
                q.append(nv)

    L = dist[N - 1]
    if L < 0:
        L = N - 1

    def feasible(d):
        if d == 0:
            return True
        if d > K:
            return False

        V = N * d + 2
        s = N * d
        t = s + 1
        dinic = Dinic(V)
        add = dinic.add_edge
        INF = K + 1

        target_base = (N - 1) * d

        # vertex 1 must have level 0, vertex N must have level d
        for i in range(d):
            add(s, target_base + i, INF)
            add(i, t, INF)

        # monotonicity: level i+1 => level i
        for v in range(N):
            base = v * d
            for i in range(1, d):
                add(base + i, base + i - 1, INF)

        for u, v in edges:
            ub = u * d
            vb = v * d

            # cost: edge is forced if level(v) = level(u) + 1
            for i in range(d):
                add(vb + i, ub + i, 1)

            # constraint: level(v) <= level(u) + 1
            for i in range(1, d):
                add(vb + i, ub + i - 1, INF)

        flow = dinic.max_flow(s, t, K + 1)
        return flow <= K

    lo = 0
    hi = min(N, K + 1, L + 1)

    while lo + 1 < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid

    print(lo)


if __name__ == "__main__":
    main()

