import sys

MOD = 998244353

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    S = data[1] if len(data) > 1 else ""

    # Build the rooted ordered forest.
    # Node 0 is a virtual root whose children are the top-level trees.
    children = [[]]
    stack = [0]

    for ch in S:
        if ch == '(':
            idx = len(children)
            children.append([])
            children[stack[-1]].append(idx)
            stack.append(idx)
        else:
            stack.pop()

    m = len(children)

    # Assign canonical IDs to unordered rooted tree types.
    type_id = [0] * m
    type_map = {(): 0}

    # Children always have larger indices than their parent.
    for v in range(m - 1, -1, -1):
        if children[v]:
            tup = tuple(sorted(type_id[c] for c in children[v]))
        else:
            tup = ()

        tid = type_map.get(tup)
        if tid is None:
            tid = len(type_map)
            type_map[tup] = tid
        type_id[v] = tid

    max_deg = max(len(ch) for ch in children)

    fact = [1] * (max_deg + 1)
    for i in range(1, max_deg + 1):
        fact[i] = fact[i - 1] * i % MOD

    invfact = [1] * (max_deg + 1)
    invfact[max_deg] = pow(fact[max_deg], MOD - 2, MOD)
    for i in range(max_deg, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    ans = 1

    # For each node, its children can be permuted arbitrarily.
    # Children of the same unordered type are indistinguishable at this node.
    for v in range(m):
        deg = len(children[v])
        ans = ans * fact[deg] % MOD

        if deg:
            cnt = {}
            for c in children[v]:
                t = type_id[c]
                cnt[t] = cnt.get(t, 0) + 1

            for k in cnt.values():
                ans = ans * invfact[k] % MOD

    print(ans)

