class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        if m == 0:
            return n * (n + 1) // 2

        by_y = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_y[b].append((a, i))

        cnt = [0] * (n + 1)
        gain = [0] * m

        max_x = 0
        second_x = 0
        unique_id = -1
        total = 0

        for r in range(1, n + 1):
            for x, idx in by_y[r]:
                if cnt[x] == 0:
                    cnt[x] = 1
                    if x > max_x:
                        second_x = max_x
                        max_x = x
                        unique_id = idx
                    elif x > second_x:
                        second_x = x
                else:
                    cnt[x] += 1
                    if x == max_x:
                        unique_id = -1
                    elif x > second_x:
                        second_x = x

            if max_x > 0 and cnt[max_x] == 1:
                gain[unique_id] += max_x - second_x

            total += r - max_x

        return total + max(gain)

