class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        # Any count larger than the requested k can be capped, because we only
        # need to know whether a block contains at least k permutations.
        INF = k + 1

        # Capped factorials: fact[i] = min(INF, i!)
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(INF, fact[i - 1] * i)

        def completions(rem_odd: int, rem_even: int, start_parity: int) -> int:
            """
            Number of valid completions using rem_odd odd numbers and
            rem_even even numbers, where the next position must have parity
            start_parity (1 = odd, 0 = even).
            """
            m = rem_odd + rem_even
            if m == 0:
                return 1

            # In an alternating sequence of even length, odd/even counts are equal.
            # In an alternating sequence of odd length, the starting parity has one more.
            if m % 2 == 0:
                if rem_odd != rem_even:
                    return 0
            else:
                if start_parity == 1:
                    if rem_odd != rem_even + 1:
                        return 0
                else:
                    if rem_even != rem_odd + 1:
                        return 0

            # Once parity slots are fixed, remaining odd numbers can be permuted
            # among odd slots and even numbers among even slots independently.
            return min(INF, fact[rem_odd] * fact[rem_even])

        used = [False] * (n + 1)
        rem_odd = (n + 1) // 2
        rem_even = n // 2
        next_parity = -1  # -1 means no parity constraint yet (first position)
        ans = []

        for _ in range(n):
            chosen = -1

            # Try candidates in increasing order to follow lexicographical order.
            for x in range(1, n + 1):
                if used[x]:
                    continue

                parity = x & 1
                if next_parity != -1 and parity != next_parity:
                    continue

                if parity == 1:
                    cnt = completions(rem_odd - 1, rem_even, 0)
                else:
                    cnt = completions(rem_odd, rem_even - 1, 1)

                if k > cnt:
                    k -= cnt
                else:
                    chosen = x
                    break

            if chosen == -1:
                return []

            ans.append(chosen)
            used[chosen] = True

            if chosen & 1:
                rem_odd -= 1
                next_parity = 0
            else:
                rem_even -= 1
                next_parity = 1

        return ans

