class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])

        # Directions in clockwise order:
        # 0: SE, 1: SW, 2: NW, 3: NE
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        clockwise = [1, 2, 3, 0]

        # f[i][j] = longest alternating diagonal ray starting at (i, j)
        # in direction (dr, dc), assuming grid[i][j] is 0 or 2.
        def build_f(dr: int, dc: int) -> List[List[int]]:
            dp = [[0] * m for _ in range(n)]
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)

            for i in rows:
                ni = i + dr
                row = grid[i]
                dp_row = dp[i]

                if 0 <= ni < n:
                    grid_ni = grid[ni]
                    dp_ni = dp[ni]

                    for j in range(m):
                        val = row[j]
                        if val == 1:
                            continue

                        nj = j + dc
                        if 0 <= nj < m:
                            need = 0 if val == 2 else 2
                            if grid_ni[nj] == need:
                                dp_row[j] = dp_ni[nj] + 1
                            else:
                                dp_row[j] = 1
                        else:
                            dp_row[j] = 1
                else:
                    for j in range(m):
                        if row[j] != 1:
                            dp_row[j] = 1

            return dp

        ans = 0

        # pref[i][j] for the current initial direction:
        # longest valid straight segment ending at (i, j)
        # while moving in that initial direction.
        pref = [[0] * m for _ in range(n)]

        for d, (dr, dc) in enumerate(dirs):
            cd = clockwise[d]
            cdr, cdc = dirs[cd]
            f_cd = build_f(cdr, cdc)

            rows = range(n) if dr == 1 else range(n - 1, -1, -1)

            for i in rows:
                qi = i - dr
                ni = i + cdr

                row = grid[i]
                pref_row = pref[i]

                qi_valid = 0 <= qi < n
                ni_valid = 0 <= ni < n

                if qi_valid:
                    prev_row = grid[qi]
                    prev_pref = pref[qi]

                if ni_valid:
                    next_row = grid[ni]
                    next_f = f_cd[ni]

                for j in range(m):
                    val = row[j]

                    if val == 1:
                        cur = 1
                    else:
                        qj = j - dc

                        if qi_valid and 0 <= qj < m:
                            qval = prev_row[qj]

                            if val == 2:
                                if qval == 1:
                                    cur = 2
                                elif qval == 0:
                                    prev_len = prev_pref[qj]
                                    cur = prev_len + 1 if prev_len else 0
                                else:
                                    cur = 0
                            else:  # val == 0
                                if qval == 2:
                                    prev_len = prev_pref[qj]
                                    cur = prev_len + 1 if prev_len else 0
                                else:
                                    cur = 0
                        else:
                            cur = 0

                    pref_row[j] = cur

                    if cur:
                        if cur > ans:
                            ans = cur

                        # If we turn clockwise here, the next expected value is:
                        # after 2 -> 0, after 0 or 1 -> 2
                        need = 0 if val == 2 else 2
                        nj = j + cdc

                        if ni_valid and 0 <= nj < m and next_row[nj] == need:
                            total = cur + next_f[nj]
                            if total > ans:
                                ans = total

        return ans

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        A, B, C = p.split('*')
        n = len(s)
        a, b, c = len(A), len(B), len(C)

        lower = a + b + c
        if lower > n:
            return -1
        if lower == 0:
            return 0

        INF = 10**18

        def occurrences(pat: str):
            m = len(pat)
            if m == 0 or m > n:
                return []

            pi = [0] * m
            for i in range(1, m):
                j = pi[i - 1]
                while j > 0 and pat[i] != pat[j]:
                    j = pi[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                pi[i] = j

            res = []
            j = 0
            for i, ch in enumerate(s):
                while j > 0 and ch != pat[j]:
                    j = pi[j - 1]
                if ch == pat[j]:
                    j += 1
                    if j == m:
                        res.append(i - m + 1)
                        j = pi[j - 1]
            return res

        def best_left(occ, m):
            if m == 0:
                return list(range(n + 1))

            arr = [-1] * (n + 1)
            for st in occ:
                end = st + m
                if st > arr[end]:
                    arr[end] = st

            cur = -1
            for i in range(n + 1):
                if arr[i] > cur:
                    cur = arr[i]
                else:
                    arr[i] = cur
            return arr

        def best_right(occ, m):
            if m == 0:
                return list(range(n + 1))

            arr = [INF] * (n + 1)
            for st in occ:
                end = st + m
                if end < arr[st]:
                    arr[st] = end

            cur = INF
            for i in range(n, -1, -1):
                if arr[i] < cur:
                    cur = arr[i]
                else:
                    arr[i] = cur
            return arr

        left_arr = best_left(occurrences(A), a)
        right_arr = best_right(occurrences(C), c)

        ans = INF

        if b == 0:
            for pos in range(n + 1):
                l = left_arr[pos]
                if l == -1:
                    continue
                r = right_arr[pos]
                if r != INF:
                    length = r - l
                    if length < ans:
                        ans = length
                        if ans == lower:
                            return ans
        else:
            for x in occurrences(B):
                l = left_arr[x]
                if l == -1:
                    continue
                r = right_arr[x + b]
                if r != INF:
                    length = r - l
                    if length < ans:
                        ans = length
                        if ans == lower:
                            return ans

        return -1 if ans == INF else ans

