MOD = 998244353

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])
    S = data[2]
    s = [ord(ch) - 97 for ch in S]

    states = 1 << N

    # popcount of each mask
    pop = [0] * states
    for mask in range(1, states):
        pop[mask] = pop[mask >> 1] + (mask & 1)

    # d[mask][i] = LCS length of S[:i] and the prefix represented by mask
    d_list = []
    for mask in range(states):
        d = [0] * (N + 1)
        for i in range(1, N + 1):
            d[i] = d[i - 1] + ((mask >> (i - 1)) & 1)
        d_list.append(d)

    # Precompute transitions, aggregating characters with the same next state
    trans = []
    for mask in range(states):
        d = d_list[mask]
        counts = {}
        for c in range(26):
            prev = 0
            nmask = 0
            for i in range(1, N + 1):
                if s[i - 1] == c:
                    val = d[i - 1] + 1
                else:
                    val = d[i] if d[i] >= prev else prev

                if val == prev + 1:
                    nmask |= 1 << (i - 1)
                prev = val

            counts[nmask] = counts.get(nmask, 0) + 1
        trans.append(list(counts.items()))

    # DP over length of the generated string
    dp = [0] * states
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * states
        for mask, val in enumerate(dp):
            if val:
                for nmask, cnt in trans[mask]:
                    ndp[nmask] = (ndp[nmask] + val * cnt) % MOD
        dp = ndp

    # Sum by final LCS length
    ans = [0] * (N + 1)
    for mask, val in enumerate(dp):
        ans[pop[mask]] = (ans[pop[mask]] + val) % MOD

    print(" ".join(map(str, ans)))

