def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, X = data[0], data[1]
    items = [[] for _ in range(3)]

    p = 2
    for _ in range(N):
        v = data[p]
        a = data[p + 1]
        c = data[p + 2]
        p += 3
        if c <= X:
            items[v - 1].append((c, a))

    if not items[0] or not items[1] or not items[2]:
        print(0)
        return

    def build_dp(lst, X):
        total_cal = 0
        for c, _ in lst:
            total_cal += c
        cap = X if total_cal > X else total_cal

        if len(lst) == 1:
            c, a = lst[0]
            dp = [0] * (cap + 1)
            if c <= cap:
                for cal in range(c, cap + 1):
                    dp[cal] = a
            if cap < X:
                dp.extend([dp[-1]] * (X - cap))
            return dp

        groups = [[] for _ in range(cap + 1)]
        for c, a in lst:
            groups[c].append(a)

        best_c = 0
        best_score = -1
        for c in range(1, cap + 1):
            vals = groups[c]
            if not vals:
                continue
            limit = cap // c
            eff = len(vals)
            if eff > limit:
                eff = limit
            score = eff * (cap - c + 1)
            if score > best_score:
                best_score = score
                best_c = c

        dp = [0] * (cap + 1)
        if best_c == 0:
            if cap < X:
                dp.extend([0] * (X - cap))
            return dp

        vals = groups[best_c]
        limit = cap // best_c
        vals.sort(reverse=True)
        if len(vals) > limit:
            del vals[limit:]

        L = len(vals)
        pref = [0] * (L + 1)
        s = 0
        for i, a in enumerate(vals, 1):
            s += a
            pref[i] = s

        for cal in range(cap + 1):
            m = cal // best_c
            if m > L:
                m = L
            dp[cal] = pref[m]

        d = dp
        for c in range(1, cap + 1):
            if c == best_c:
                continue
            vals = groups[c]
            if not vals:
                continue

            limit = cap // c
            if len(vals) > 1:
                vals.sort(reverse=True)
            if len(vals) > limit:
                del vals[limit:]

            rng = range(cap, c - 1, -1)
            for a in vals:
                for cal in rng:
                    nv = d[cal - c] + a
                    if nv > d[cal]:
                        d[cal] = nv

        m = 0
        for i in range(cap + 1):
            v = dp[i]
            if v < m:
                dp[i] = m
            else:
                m = v

        if cap < X:
            dp.extend([dp[-1]] * (X - cap))
        return dp

    dps = [build_dp(items[i], X) for i in range(3)]

    high = min(dp[-1] for dp in dps) + 1
    low = 0

    def feasible(t):
        total = 0
        for dp in dps:
            pos = bisect_left(dp, t)
            if pos > X:
                return False
            total += pos
            if total > X:
                return False
        return True

    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid

    print(low)


