import sys


def interpolate(values, P):
    d = len(values) - 1
    y = values[:]

    # Newton forward coefficients: Δ^k F(0)
    newton = []
    for k in range(d + 1):
        newton.append(y[0] % P)
        for i in range(d - k):
            y[i] = (y[i + 1] - y[i]) % P

    # inverses of 1..d+1
    inv = [0] * (d + 2)
    if d + 1 >= 1:
        inv[1] = 1
    for i in range(2, d + 2):
        inv[i] = (P - (P // i) * inv[P % i] % P) % P

    # Convert sum newton[k] * binom(x, k) to power basis.
    res = [0] * (d + 1)
    binom = [1]  # binom(x, 0)

    for k in range(d + 1):
        coeff = newton[k]
        if coeff:
            for i, c in enumerate(binom):
                if c:
                    res[i] = (res[i] + coeff * c) % P

        if k == d:
            break

        # binom(x, k+1) = binom(x, k) * (x - k) / (k+1)
        new = [0] * (len(binom) + 1)
        km = k % P
        for i, c in enumerate(binom):
            if c:
                new[i] = (new[i] - km * c) % P
                new[i + 1] = (new[i + 1] + c) % P

        invk = inv[k + 1]
        for i in range(len(new)):
            new[i] = new[i] * invk % P
        binom = new

    return res


def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    P = int(data[1])

    E = N * (N - 1) // 2
    K = N // 2
    C2 = [i * (i - 1) // 2 for i in range(N + 1)]

    # Maximum possible degree (maximum number of edges) among valid BFS-layer sequences.
    NEG = -10**9
    maxdp = [[[[NEG] * 2 for _ in range(N + 1)] for _ in range(K + 1)] for __ in range(N + 1)]
    maxdp[1][1][1][0] = 0

    for n in range(1, N):
        for e in range(K + 1):
            for a in range(1, n + 1):
                for p in range(2):
                    val = maxdp[n][e][a][p]
                    if val < 0:
                        continue
                    rem = N - n
                    for b in range(1, rem + 1):
                        ne = e + (b if p == 1 else 0)
                        if ne <= K:
                            nv = val + C2[b] + a * b
                            if nv > maxdp[n + b][ne][b][1 - p]:
                                maxdp[n + b][ne][b][1 - p] = nv

    Dmax = 0
    for a in range(1, N + 1):
        for p in range(2):
            if maxdp[N][K][a][p] > Dmax:
                Dmax = maxdp[N][K][a][p]
    del maxdp

    d = min(max(Dmax, N - 1), E)

    # Binomial coefficients modulo P.
    C = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(N + 1):
        C[i][0] = C[i][i] = 1
        for j in range(1, i):
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % P

    # Flat DP index: (used_vertices, last_layer_size, last_parity)
    stride = N + 1
    size = stride * stride * 2

    def idx(n, a, p):
        return ((n * stride + a) << 1) | p

    # Transitions.
    # p = 0: next layer is odd, even count does not increase.
    # p = 1: next layer is even, even count increases by b.
    trans0 = [[] for _ in range(N + 1)]
    trans1 = [[] for _ in range(N + 1)]

    # Lane width for packing even-count coefficients into one Python integer.
    # Each lane is large enough to avoid carries before normalization.
    W = 72

    for n in range(1, N):
        rem = N - n
        for b in range(1, rem + 1):
            t0 = idx(n + b, b, 1)
            trans0[n].append((t0, b, C[rem][b]))
            if b <= K:
                t1 = idx(n + b, b, 0)
                trans1[n].append((t1, b, b * W, C[rem][b]))

    a_ranges = [None] * (N + 1)
    a_ranges[1] = range(1, 2)
    for n in range(2, N + 1):
        a_ranges[n] = range(1, n)

    MASK_LANE = (1 << W) - 1
    keep_masks = [0] * (K + 1)
    for add in range(K + 1):
        keep_masks[add] = (1 << (W * (K - add + 1))) - 1

    def normalize(x, P=P, MASK=MASK_LANE, W=W):
        """Reduce every packed lane modulo P."""
        res = 0
        shift = 0
        while x:
            lane = x & MASK
            if lane:
                lane %= P
                if lane:
                    res |= lane << shift
            x >>= W
            shift += W
        return res

    norm = normalize
    keep = keep_masks
    tr0_all = trans0
    tr1_all = trans1
    aranges = a_ranges

    # F(0) = 0 because every connected graph has at least N-1 edges.
    values = [0]

    for x in range(1, d + 1):
        base = (1 + x) % P

        powb = [1] * (E + 1)
        for i in range(1, E + 1):
            powb[i] = powb[i - 1] * base % P

        powb_c2 = [powb[c] for c in C2]

        # H[a][b] = ((1+x)^a - 1)^b * (1+x)^{C(b,2)}
        H = [[0] * (N + 1) for _ in range(N + 1)]
        for a in range(1, N + 1):
            t = powb[a] - 1
            if t < 0:
                t += P
            val = 1
            Ha = H[a]
            for b in range(1, N + 1):
                val = val * t % P
                Ha[b] = val * powb_c2[b] % P

        dp = [0] * size
        dp[idx(1, 1, 0)] = 1 << W  # even count = 1 (vertex 1)

        for n in range(1, N):
            base_n = n * stride

            # Current layer parity 0 -> next parity 1, add 0 to even count.
            tr0 = tr0_all[n]
            if tr0:
                for a in aranges[n]:
                    sidx = (base_n + a) << 1
                    src = dp[sidx]
                    if not src:
                        continue
                    src = norm(src)
                    dp[sidx] = src
                    if not src:
                        continue

                    Ha = H[a]
                    for tidx, b, cb in tr0:
                        h = Ha[b]
                        if h:
                            w = (cb * h) % P
                            if w:
                                dp[tidx] += src * w
                    dp[sidx] = 0

            # Current layer parity 1 -> next parity 0, add b to even count.
            tr1 = tr1_all[n]
            if tr1:
                for a in aranges[n]:
                    sidx = ((base_n + a) << 1) | 1
                    src = dp[sidx]
                    if not src:
                        continue
                    src = norm(src)
                    dp[sidx] = src
                    if not src:
                        continue

                    Ha = H[a]
                    for tidx, b, sh, cb in tr1:
                        src_low = src & keep[b]
                        if not src_low:
                            continue
                        h = Ha[b]
                        if h:
                            w = (cb * h) % P
                            if w:
                                dp[tidx] += (src_low * w) << sh
                    dp[sidx] = 0

        y = 0
        final_base = N * stride
        shiftK = K * W
        for a in range(1, N):
            i0 = (final_base + a) << 1
            y += (dp[i0] >> shiftK) & MASK_LANE
            y += (dp[i0 | 1] >> shiftK) & MASK_LANE

        values.append(y % P)

    coeff = interpolate(values, P)

    out = []
    for m in range(N - 1, E + 1):
        if m <= d:
            out.append(str(coeff[m] % P))
        else:
            out.append("0")

    sys.stdout.write(" ".join(out) + "\n")


