    solve()

import sys
import math


def matmul(X, Y, p):
    n = len(X)
    Z = []
    rng = range(n)
    for i in rng:
        Xi = X[i]
        Zi = [0] * n
        for k, a in enumerate(Xi):
            if a:
                Yk = Y[k]
                for j in rng:
                    Zi[j] += a * Yk[j]
        Z.append([x % p for x in Zi])
    return Z


def identity(n):
    return [[1 if i == j else 0 for j in range(n)] for i in range(n)]


def mat_pow(A, e, p):
    n = len(A)
    result = None
    base = A
    while e:
        if e & 1:
            if result is None:
                result = [row[:] for row in base]
            else:
                result = matmul(result, base, p)
        e >>= 1
        if e:
            base = matmul(base, base, p)
    if result is None:
        return identity(n)
    return result


def charpoly(A, p):
    n = len(A)
    H = [row[:] for row in A]

    # Reduce to upper Hessenberg form by similarity transformations.
    for m in range(n - 1):
        q = m + 1
        pivot = -1
        for i in range(q, n):
            if H[i][m]:
                pivot = i
                break
        if pivot == -1:
            continue

        if pivot != q:
            H[q], H[pivot] = H[pivot], H[q]
            for row in H:
                row[q], row[pivot] = row[pivot], row[q]

        inv = pow(H[q][m], p - 2, p)
        for r in range(q + 1, n):
            val = H[r][m]
            if val:
                factor = val * inv % p
                row_r = H[r]
                row_q = H[q]

                for c in range(m, n):
                    row_r[c] = (row_r[c] - factor * row_q[c]) % p

                for i in range(n):
                    H[i][q] = (H[i][q] + factor * H[i][r]) % p

                H[r][m] = 0

    # Characteristic polynomial of an upper Hessenberg matrix.
    polys = [[1]]
    for k in range(n):
        pk = polys[k]
        new = [0] + pk[:]

        hkk = H[k][k] % p
        if hkk:
            for i, c in enumerate(pk):
                new[i] = (new[i] - hkk * c) % p

        prod = 1
        for i in range(k - 1, -1, -1):
            prod = prod * H[i + 1][i] % p
            coeff = H[i][k] * prod % p
            if coeff:
                pi = polys[i]
                for j, c in enumerate(pi):
                    new[j] = (new[j] - coeff * c) % p

        for i in range(k + 2):
            new[i] %= p
        polys.append(new)

    return polys[n]


def poly_mul(a, b, chi, p):
    n = len(chi) - 1
    tmp = [0] * (2 * n - 1)

    for i, ai in enumerate(a):
        if ai:
            for j, bj in enumerate(b):
                if bj:
                    tmp[i + j] += ai * bj

    for deg in range(2 * n - 2, n - 1, -1):
        c = tmp[deg] % p
        if c:
            shift = deg - n
            for i in range(n):
                tmp[shift + i] -= c * chi[i]

    return [tmp[i] % p for i in range(n)]


def poly_pow_x(exp, chi, p):
    n = len(chi) - 1

    if exp < n:
        res = [0] * n
        res[exp] = 1
        return res

    res = [0] * n
    res[0] = 1

    if n == 1:
        base = [(-chi[0]) % p]
    else:
        base = [0] * n
        base[1] = 1

    e = exp
    while e:
        if e & 1:
            res = poly_mul(res, base, chi, p)
        e >>= 1
        if e:
            base = poly_mul(base, base, chi, p)

    return res


def eval_poly(A, coeffs, p):
    n = len(A)

    d = len(coeffs) - 1
    while d > 0 and coeffs[d] % p == 0:
        d -= 1
    coeffs = coeffs[:d + 1]

    if d == 0:
        c = coeffs[0] % p
        if c == 0:
            return [[0] * n for _ in range(n)]
        return [[c if i == j else 0 for j in range(n)] for i in range(n)]

    # Small degree: Horner is cheaper.
    if d <= 5:
        res = [[0] * n for _ in range(n)]
        c = coeffs[d] % p
        if c:
            for i in range(n):
                res[i][i] = c

        for idx in range(d - 1, -1, -1):
            res = matmul(res, A, p)
            c = coeffs[idx] % p
            if c:
                for i in range(n):
                    v = res[i][i] + c
                    if v >= p:
                        v -= p
                    res[i][i] = v
        return res

    # Paterson-Stockmeyer evaluation.
    m = math.isqrt(d) + 1
    q = d // m

    powers = [identity(n)]
    for _ in range(m):
        powers.append(matmul(powers[-1], A, p))

    blocks = []
    for k in range(q + 1):
        S = [[0] * n for _ in range(n)]
        base = k * m
        max_t = min(m, d - base + 1)

        for t in range(max_t):
            c = coeffs[base + t] % p
            if c:
                P = powers[t]
                for i in range(n):
                    Si = S[i]
                    Pi = P[i]
                    for j in range(n):
                        Si[j] += c * Pi[j]

        for i in range(n):
            Si = S[i]
            for j in range(n):
                Si[j] %= p

        blocks.append(S)

    res = blocks[q]
    Am = powers[m]

    for k in range(q - 1, -1, -1):
        res = matmul(res, Am, p)
        S = blocks[k]
        for i in range(n):
            Ri = res[i]
            Si = S[i]
            for j in range(n):
                v = Ri[j] + Si[j]
                if v >= p:
                    v -= p
                Ri[j] = v

    return res


def compute_Ap(A, p):
    n = len(A)
    if n == 1:
        return [[pow(A[0][0], p, p)]]

    try:
        pc = p.bit_count()
    except AttributeError:
        pc = bin(p).count("1")

    binary_mults = (p.bit_length() - 1) + (pc - 1)

    if binary_mults <= 20:
        return mat_pow(A, p, p)

    chi = charpoly(A, p)
    coeffs = poly_pow_x(p, chi, p)
    return eval_poly(A, coeffs, p)


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, p = data[0], data[1]
    vals = data[2:]

    A = []
    zeros = []
    idx = 0
    for i in range(N):
        row = vals[idx:idx + N]
        idx += N
        A.append(row)
        for j, v in enumerate(row):
            if v == 0:
                zeros.append((i, j))

    K = len(zeros)

    if p == 1:
        sys.stdout.write("\n".join(" ".join(["0"] * N) for _ in range(N)))
        return

    if p == 2:
        rows = []
        cols = [0] * N

        for i in range(N):
            bits = 0
            for j, v in enumerate(A[i]):
                if v == 0:
                    v = 1
                if v & 1:
                    bits |= 1 << j
                    cols[j] |= 1 << i
            rows.append(bits)

        out = []
        for i in range(N):
            ri = rows[i]
            out.append(" ".join(str((ri & cols[j]).bit_count() & 1) for j in range(N)))
        sys.stdout.write("\n".join(out))
        return

    Ap = compute_Ap(A, p)
    total = [row[:] for row in Ap]

    if p == 3:
        for i, j in zeros:
            if i == j:
                for r in range(N):
                    if r != i:
                        a = A[r][i]
                        if a:
                            v = total[r][i] + a
                            if v >= p:
                                v -= p
                            total[r][i] = v

                for c in range(N):
                    if c != i:
                        a = A[i][c]
                        if a:
                            v = total[i][c] + a
                            if v >= p:
                                v -= p
                            total[i][c] = v
            else:
                a = A[j][i]
                if a:
                    v = total[i][j] + a
                    if v >= p:
                        v -= p
                    total[i][j] = v
    else:
        for i, j in zeros:
            if i == j:
                for r in range(N):
                    if r != i:
                        a = A[r][i]
                        if a:
                            v = total[r][i] + a
                            if v >= p:
                                v -= p
                            total[r][i] = v

                for c in range(N):
                    if c != i:
                        a = A[i][c]
                        if a:
                            v = total[i][c] + a
                            if v >= p:
                                v -= p
                            total[i][c] = v

    if K & 1:
        for i in range(N):
            row = total[i]
            for j in range(N):
                if row[j]:
                    row[j] = p - row[j]

    sys.stdout.write("\n".join(" ".join(map(str, total[i])) for i in range(N)))


if __name__ == "__main__":
    solve()

from typing import List
from bisect import bisect_left

class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        n = len(intervals)
        if n == 0:
            return []

        # Sort by right endpoint. Keep original index for lexicographic tie-breaking.
        arr = [(r, l, w, idx) for idx, (l, r, w) in enumerate(intervals)]
        arr.sort()

        ends = [x[0] for x in arr]

        # prev[i] = number of intervals before i whose right endpoint is strictly < l_i.
        prev = [bisect_left(ends, arr[i][1], 0, i) for i in range(n)]

        NEG = -1

        # score[k][i] = maximum score using exactly k intervals among first i intervals.
        # choice[k][i] = lexicographically smallest sorted tuple of indices achieving it.
        score = [[NEG] * (n + 1) for _ in range(5)]
        choice = [[None] * (n + 1) for _ in range(5)]

        for j in range(n + 1):
            score[0][j] = 0
            choice[0][j] = ()

        def add_index(tup: tuple, x: int) -> tuple:
            """Insert x into a sorted tuple of length at most 3."""
            m = len(tup)
            if m == 0:
                return (x,)
            if m == 1:
                a = tup[0]
                return (x, a) if x < a else (a, x)
            if m == 2:
                a, b = tup
                if x < a:
                    return (x, a, b)
                if x < b:
                    return (a, x, b)
                return (a, b, x)

            a, b, c = tup
            if x < a:
                return (x, a, b, c)
            if x < b:
                return (a, x, b, c)
            if x < c:
                return (a, b, x, c)
            return (a, b, c, x)

        for i in range(1, n + 1):
            _, l, w, idx = arr[i - 1]
            p = prev[i - 1]
            limit = min(4, i)

            for k in range(1, limit + 1):
                # Option 1: skip interval i.
                best_s = score[k][i - 1]
                best_c = choice[k][i - 1]

                # Option 2: take interval i.
                if score[k - 1][p] != NEG:
                    s = score[k - 1][p] + w

                    if s > best_s:
                        best_s = s
                        best_c = add_index(choice[k - 1][p], idx)
                    elif s == best_s:
                        c = add_index(choice[k - 1][p], idx)
                        if best_c is None or c < best_c:
                            best_c = c

                score[k][i] = best_s
                choice[k][i] = best_c

        best_s = -1
        best_c = ()

        for k in range(5):
            s = score[k][n]
            c = choice[k][n]
            if s > best_s or (s == best_s and c is not None and c < best_c):
                best_s = s
                best_c = c

        return list(best_c)

import sys
from collections import deque

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, M = data[0], data[1]
    A = [x - 1 for x in data[2:2 + N]]

    indeg = [0] * N
    for a in A:
        indeg[a] += 1

    # Find cycle nodes by Kahn's algorithm.
    indeg2 = indeg[:]
    q = deque([i for i in range(N) if indeg2[i] == 0])
    while q:
        v = q.popleft()
        u = A[v]
        indeg2[u] -= 1
        if indeg2[u] == 0:
            q.append(u)

    is_cycle = [indeg2[i] > 0 for i in range(N)]

    # DP on trees attached to cycles.
    # For a non-cycle node v, prod[v][c] is the product of DP values
    # of already processed children at value c.
    rem = indeg[:]
    q = deque([i for i in range(N) if not is_cycle[i] and rem[i] == 0])

    prod = [None] * N
    acc = [None] * N  # accumulators for cycle nodes

    M1 = M + 1
    rng = range(1, M1)
    mod = MOD

    leaf = list(range(M1))  # DP array for a leaf: H(c) = c
    leaf_copy = leaf.copy

    while q:
        v = q.popleft()

        arr = prod[v]
        prod[v] = None

        if arr is None:
            # Leaf.
            arr = leaf_copy()
        else:
            # Prefix sum: H_v(c) = sum_{t=1}^c prod_children(t)
            s = 0
            for c in rng:
                s += arr[c]
                if s >= mod:
                    s -= mod
                arr[c] = s

        p = A[v]

        if is_cycle[p]:
            a = acc[p]
            if a is None:
                acc[p] = arr
            else:
                for c in rng:
                    a[c] = (a[c] * arr[c]) % mod
        else:
            a = prod[p]
            if a is None:
                prod[p] = arr
            else:
                for c in rng:
                    a[c] = (a[c] * arr[c]) % mod

            rem[p] -= 1
            if rem[p] == 0:
                q.append(p)

    # Combine each cycle component.
    visited = [False] * N
    ans = 1

    for i in range(N):
        if is_cycle[i] and not visited[i]:
            cur = i
            Q = None

            while not visited[cur]:
                visited[cur] = True

                a = acc[cur]
                if a is not None:
                    acc[cur] = None
                    if Q is None:
                        Q = a
                    else:
                        for c in rng:
                            Q[c] = (Q[c] * a[c]) % mod

                cur = A[cur]

            if Q is None:
                comp_sum = M % mod
            else:
                s = 0
                for c in rng:
                    s += Q[c]
                    if s >= mod:
                        s -= mod
                comp_sum = s

            ans = (ans * comp_sum) % mod

    print(ans)


