from collections import deque

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        if n == 0:
            return 0

        bits = [1 if ch == '1' else 0 for ch in s]

        # Current maximum run length (answer with 0 operations).
        max_run = 1
        cur = 1
        for i in range(1, n):
            if bits[i] == bits[i - 1]:
                cur += 1
                if cur > max_run:
                    max_run = cur
            else:
                cur = 1

        if max_run == 1:
            return 1

        if numOps == 0:
            return max_run

        # If we can make the string alternating, answer is 1.
        mism0 = 0  # pattern 0101...
        mism1 = 0  # pattern 1010...
        for i, bit in enumerate(bits):
            if bit != (i & 1):
                mism0 += 1
            if bit != (1 - (i & 1)):
                mism1 += 1

        if min(mism0, mism1) <= numOps:
            return 1

        # pref0[i] = flips needed to make s[:i] all '0'
        # pref1[i] = flips needed to make s[:i] all '1'
        pref0 = [0] * (n + 1)
        pref1 = [0] * (n + 1)
        for i, bit in enumerate(bits):
            pref0[i + 1] = pref0[i] + bit
            pref1[i + 1] = pref1[i] + (1 - bit)

        INF = numOps + 1

        def can(limit: int) -> bool:
            # dp0[i] / dp1[i]: min flips for prefix ending with 0 / 1
            # with all runs <= limit.
            #
            # For a run of 0s starting at j and ending at i:
            # cost = dp1[j-1] + pref0[i+1] - pref0[j]
            #      = pref0[i+1] + (dp1[j-1] - pref0[j])
            #
            # Maintain sliding minimum of (dp_other[j-1] - pref_current[j])
            # over valid starts j with i-j+1 <= limit.
            dq0 = deque([(0, 0)])  # (start_index, value) for ending with 0
            dq1 = deque([(0, 0)])  # (start_index, value) for ending with 1

            prev0 = INF
            prev1 = INF

            for i in range(n):
                # Add start position j = i for runs ending at future positions.
                if i > 0:
                    if prev1 <= numOps:
                        val = prev1 - pref0[i]
                        while dq0 and dq0[-1][1] >= val:
                            dq0.pop()
                        dq0.append((i, val))

                    if prev0 <= numOps:
                        val = prev0 - pref1[i]
                        while dq1 and dq1[-1][1] >= val:
                            dq1.pop()
                        dq1.append((i, val))

                # Remove starts that would create a run longer than limit.
                left = i - limit + 1
                while dq0 and dq0[0][0] < left:
                    dq0.popleft()
                while dq1 and dq1[0][0] < left:
                    dq1.popleft()

                if dq0:
                    dp0 = pref0[i + 1] + dq0[0][1]
                    if dp0 > numOps:
                        dp0 = INF
                else:
                    dp0 = INF

                if dq1:
                    dp1 = pref1[i + 1] + dq1[0][1]
                    if dp1 > numOps:
                        dp1 = INF
                else:
                    dp1 = INF

                prev0, prev1 = dp0, dp1

                if prev0 == INF and prev1 == INF:
                    return False

            return prev0 <= numOps or prev1 <= numOps

        # Answer 1 has already been ruled out.
        lo, hi = 2, max_run
        while lo < hi:
            mid = (lo + hi) // 2
            if can(mid):
                hi = mid
            else:
                lo = mid + 1

        return lo

from typing import List

class Solution:
    def subsequencesWithMiddleMode(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)

        def c2(x: int) -> int:
            return x * (x - 1) // 2

        right = {}
        for v in nums:
            right[v] = right.get(v, 0) + 1

        left = {}
        ans = 0

        for m, x in enumerate(nums):
            right[x] -= 1
            if right[x] == 0:
                del right[x]

            L = m
            R = n - m - 1

            if L >= 2 and R >= 2:
                cxL = left.get(x, 0)
                cxR = right.get(x, 0)

                Lnon = L - cxL
                Rnon = R - cxR

                L0 = c2(Lnon)
                L1 = cxL * Lnon
                L2 = c2(cxL)

                R0 = c2(Rnon)
                R1 = cxR * Rnon
                R2 = c2(cxR)

                # Cases where x appears at least 3 times in the full subsequence.
                valid = (
                    L0 * R2 + L1 * R1 + L2 * R0 +
                    L1 * R2 + L2 * R1 + L2 * R2
                )

                # Case where x appears exactly twice total, and x is on the left side.
                if cxL and Lnon and Rnon >= 2:
                    r_dist = c2(Rnon)
                    for v, c in right.items():
                        if v != x:
                            r_dist -= c * (c - 1) // 2

                    s = 0
                    for u, cu in left.items():
                        if u == x:
                            continue
                        cr = right.get(u, 0)
                        s += cu * (r_dist - cr * (Rnon - cr))

                    valid += cxL * s

                # Case where x appears exactly twice total, and x is on the right side.
                if cxR and Rnon and Lnon >= 2:
                    l_dist = c2(Lnon)
                    for v, c in left.items():
                        if v != x:
                            l_dist -= c * (c - 1) // 2

                    s = 0
                    for w, cw in right.items():
                        if w == x:
                            continue
                        cl = left.get(w, 0)
                        s += cw * (l_dist - cl * (Lnon - cl))

                    valid += cxR * s

                ans = (ans + valid) % MOD

            left[x] = left.get(x, 0) + 1

        return ans

import sys


def solve():
    it = map(int, sys.stdin.buffer.read().split())
    try:
        N = next(it)
    except StopIteration:
        return

    adj = [[] for _ in range(N + 1)]
    deg = [0] * (N + 1)

    for u, v in zip(it, it):
        adj[u].append(v)
        adj[v].append(u)
        deg[u] += 1
        deg[v] += 1
    del it

    best = 3

    for c in range(1, N + 1):
        if best == N:
            break

        d = deg[c]

        if d == 1:
            nd = deg[adj[c][0]]
            if nd >= 2:
                cand = nd + 1
                if cand > best:
                    best = cand

        elif d == 2:
            a, b = adj[c]
            da = deg[a]
            db = deg[b]

            if da >= 2:
                if db >= 2:
                    if da < db:
                        da, db = db, da
                    cand = da if da > db * 2 else db * 2
                    cand += 1
                else:
                    cand = da + 1

                if cand > best:
                    best = cand

            elif db >= 2:
                cand = db + 1
                if cand > best:
                    best = cand

        else:
            vals = [deg[nb] for nb in adj[c] if deg[nb] >= 2]
            m = len(vals)

            if m == 0:
                continue

            if m == 1:
                cand = vals[0] + 1

            elif m == 2:
                da, db = vals
                if da < db:
                    da, db = db, da
                cand = (da if da > db * 2 else db * 2) + 1

            elif m == 3:
                a, b, cval = vals

                if a < b:
                    a, b = b, a
                if b < cval:
                    b, cval = cval, b
                if a < b:
                    a, b = b, a

                cand = a
                p = b * 2
                if p > cand:
                    cand = p
                p = cval * 3
                if p > cand:
                    cand = p
                cand += 1

            elif m == 4:
                a, b, cval, dval = vals

                if a < b:
                    a, b = b, a
                if cval < dval:
                    cval, dval = dval, cval
                if a < cval:
                    a, cval = cval, a
                if b < dval:
                    b, dval = dval, b
                if b < cval:
                    b, cval = cval, b

                cand = a
                p = b * 2
                if p > cand:
                    cand = p
                p = cval * 3
                if p > cand:
                    cand = p
                p = dval * 4
                if p > cand:
                    cand = p
                cand += 1

            else:
                vals.sort(reverse=True)
                maxprod = 0
                i = 1
                for dd in vals:
                    prod = i * dd
                    if prod > maxprod:
                        maxprod = prod
                    i += 1
                cand = maxprod + 1

            if cand > best:
                best = cand

    print(N - best)


if __name__ == "__main__":
    solve()

from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        T = threshold

        parent = list(range(T + 1))
        size = [1] * (T + 1)

        # first[k] stores one present number that divides k.
        # All present divisors of k are unioned through this representative.
        first = [-1] * (T + 1)

        components = len(nums)

        for a in nums:
            # Any value greater than threshold cannot have lcm <= threshold
            # with any other value, so it remains isolated.
            if a > T:
                continue

            # Find root of a once, then maintain it while unioning.
            ra = a
            while parent[ra] != ra:
                parent[ra] = parent[parent[ra]]
                ra = parent[ra]

            for k in range(a, T + 1, a):
                f = first[k]

                if f == -1:
                    first[k] = a
                elif f != a:
                    # Find root of f.
                    rb = f
                    while parent[rb] != rb:
                        parent[rb] = parent[parent[rb]]
                        rb = parent[rb]

                    if ra != rb:
                        if size[ra] < size[rb]:
                            parent[ra] = rb
                            size[rb] += size[ra]
                            ra = rb
                        else:
                            parent[rb] = ra
                            size[ra] += size[rb]

                        components -= 1

        return components
